import{_ as t,o as a,c as r,a5 as d}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"可持续的小生意：把范围、价格、交付、回款与容量放进同一张账本","description":"用明确范围的服务和假设数字练习定价、全流程工时、单次交付余量、回款与容量管理，检查生意能否在可承担的投入内持续运转。","frontmatter":{"title":"可持续的小生意：把范围、价格、交付、回款与容量放进同一张账本","description":"用明确范围的服务和假设数字练习定价、全流程工时、单次交付余量、回款与容量管理，检查生意能否在可承担的投入内持续运转。","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"threads/practice/sustainable-business.md","filePath":"threads/practice/sustainable-business.md","lastUpdated":1789776000000}'),o={name:"threads/practice/sustainable-business.md"};function s(n,e,p,i,c,h){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="可持续的小生意" tabindex="-1">可持续的小生意 <a class="header-anchor" href="#可持续的小生意" aria-label="Permalink to &quot;可持续的小生意&quot;">​</a></h1><p><a href="./customer-discovery">找到首批用户</a> 回答“是否有人需要并愿意试一次”；可持续经营还要回答“能否按承诺交付，收到款项，并有余力服务下一位用户”。订单、收入、到账和可用时间是不同的记录，不能拿其中一个代替其他三个。</p><p>本页是 <a href="./../part-2/entrepreneurship">创业篇</a> 与 <a href="./../part-3/2-ai-development-and-resource-layer">AI 学习、项目开发与资源层创业</a> 的实操补充，把其中的交付和经营问题拆为可记录的工作。它是一套经营观察练习，数字均为假设，框架属于本指南建议。示例不包含完整税务、会计或合同处理，不能用于推算实际净利润或替代专业意见。</p><h2 id="_1-先给服务划出边界" tabindex="-1">1. 先给服务划出边界 <a class="header-anchor" href="#_1-先给服务划出边界" aria-label="Permalink to &quot;1. 先给服务划出边界&quot;">​</a></h2><p>把“帮你用好 AI”改写成可以验收的服务：为一份已获授权、结构符合要求的资料制作一个内部检索原型，交付演示、测试记录和操作说明。正式上线、持续维护、追加数据和额外培训需要另行确认。边界越含糊，双方越容易对“已经完成”产生不同理解。</p><p>一张服务说明至少应包含：适合谁、解决哪项任务、客户提供什么、交付物、验收条件、数量与期限、包含的修改，以及超出范围后的处理。对不适合的客户也写清原因，例如无法提供必要材料，或需要你尚不能保证的响应时间。</p><p>客户提出新需求时，先区分三件事：原交付未达约定、原范围内的修改、真正新增的工作。不能把修复自己的遗漏都算作加价，也不能让一个有限服务悄悄变成无限承诺。将影响和新安排确认后，再开始新增部分。</p><h2 id="_2-定价也是一项实验" tabindex="-1">2. 定价也是一项实验 <a class="header-anchor" href="#_2-定价也是一项实验" aria-label="Permalink to &quot;2. 定价也是一项实验&quot;">​</a></h2><p>价格假设可以写成：“对这个范围，目标客户是否接受这个价格，且实际交付投入是否在上限内？”展示清楚的价格和范围，记录接触人数、正式报价人数、接受人数、拒绝原因和已到账金额。</p><p>一轮先保持服务范围相近。如果同时换了人群、渠道、价格和交付内容，就很难解释转化变化。小样本无法给出精确的需求曲线；一次没成交，也可能是时间、信任或内部审批不匹配。不要把所有拒绝都理解为“太贵”。</p><p>折扣必须有清楚的范围和期限，不制造不存在的原价或稀缺名额。试点价得到接受后，还需要检验常规定价。不同报价带来的比较也应记录客户条件差异，不能把两位不同客户当成严格对照实验。</p><h2 id="_3-把自己的时间写进示例" tabindex="-1">3. 把自己的时间写进示例 <a class="header-anchor" href="#_3-把自己的时间写进示例" aria-label="Permalink to &quot;3. 把自己的时间写进示例&quot;">​</a></h2><p>假设一次资料整理服务，价格为 1,200 元，已全额到账。先记录可以归属到这一单的支出和工时：</p><table tabindex="0"><thead><tr><th>项目</th><th>假设金额或时间</th></tr></thead><tbody><tr><td>工具与外部处理支出</td><td>120 元</td></tr><tr><td>外部协助支出</td><td>80 元</td></tr><tr><td>分摊到本单的获客现金支出</td><td>150 元</td></tr><tr><td>沟通与报价</td><td>1 小时</td></tr><tr><td>材料准备</td><td>1 小时</td></tr><tr><td>制作</td><td>3 小时</td></tr><tr><td>修改</td><td>1 小时</td></tr><tr><td>交接与后续支持</td><td>1 小时</td></tr></tbody></table><p>直接现金支出为 <code>120 + 80 + 150 = 350 元</code>，扣除这些支出后剩 <code>1,200 - 350 = 850 元</code>。全流程共 <code>7 小时</code>，不是只计算制作的 <code>3 小时</code>。</p><p>为了观察时间代价，假设内部按每小时 80 元为自己的工时计入一个比较值，则本单工时比较值为 <code>7 × 80 = 560 元</code>，再扣除它还剩 <code>850 - 560 = 290 元</code>。这里的每小时 80 元只是演示假设，不能当作工资建议；自己的时间没有实际付现，也不等于没有代价。</p><p>这 290 元还没有扣除公共固定支出、未分摊的试错、税费和其他遗漏成本，所以不是净利润。如果返工增加 4 小时，按同一比较值又增加 320 元，本单余量变为 <code>-30 元</code>。这个例子说明需要记录返工，不能推出整个业务必然亏损。</p><p>获客支出也不能只分给成交者而忽略未成交活动。本例的 150 元已假设包含这一周期失败尝试的分摊；现实中应留下分摊方法，避免看起来每单赚钱，整体现金却减少。</p><h2 id="_4-同时看到账和承诺" tabindex="-1">4. 同时看到账和承诺 <a class="header-anchor" href="#_4-同时看到账和承诺" aria-label="Permalink to &quot;4. 同时看到账和承诺&quot;">​</a></h2><p>在经营记录里分别列出：已报价、已接受、已交付、已验收、应收、到账和退款。做了工作尚未到账，与款已到账但尚未履约，都需要单独看。客户预付款会增加当前余额，同时也带来未完成的交付义务，不能全部当成可以自由使用的余量。</p><p>可以维护一个简单的未来四周视图：期初可用现金、已确定的支出、预计到账日期、未完成承诺。预计到账标注依据和不确定性，口头意向不要写成确定回款。若一笔款延迟，重新检查哪些已承诺工作仍能完成，及时与相关方确认安排，而不是用更多未验证订单掩盖缺口。</p><p>具体付款、退款和合同安排应按真实业务另行确认。本页关心的是记录是否能反映现实，不提供通用的预收比例或借款建议。</p><h2 id="_5-容量由整条流程决定" tabindex="-1">5. 容量由整条流程决定 <a class="header-anchor" href="#_5-容量由整条流程决定" aria-label="Permalink to &quot;5. 容量由整条流程决定&quot;">​</a></h2><p>假设每周可以为生意安排 20 小时，预留 6 小时处理公共管理、学习和意外，只剩 14 小时可用于包含获客在内的订单流程。按每单 7 小时计算，账面容量是 2 单；这不是每周必须接满的指标。</p><p>若同周有一单多出 4 小时返工，就不能仍假装 14 小时内能完成全部工作。交付还可能被客户反馈等待、第三方排期或批量任务限制，因此把“可工作时数”和“承诺完成日期”分开。新增订单前，查看已承诺的工作，而不是只看日历上有没有空白。</p><p>连续超时需要回到范围、输入质量、修改次数和价格逐项检查。先移除没有价值的步骤，保留必要核对；不能为了让账本好看而取消关键验收。AI 辅助节约的时间，也要扣除提示、审核、纠错和维护后再记录。</p><h2 id="_6-交付之后再观察复购" tabindex="-1">6. 交付之后再观察复购 <a class="header-anchor" href="#_6-交付之后再观察复购" aria-label="Permalink to &quot;6. 交付之后再观察复购&quot;">​</a></h2><p>验收要能执行。例如约定字段完整、样本核对通过、操作说明可由客户照着完成；“满意为止”既不能帮助交付，也无法解释成本。交接时记录版本、已知限制、确认人、尚未解决的问题和后续支持边界。</p><p>复购意味着对方再次购买某种结果，但要记录原因：任务按周发生、第一次未完成被迫补做、促销带来购买，含义不同。客户不再购买也未必是交付失败，一次性任务完成本来就可能没有第二单。</p><p>每周抽出一个固定时段，核对本周订单的真实工时、到账、返工、未履约工作和用户反馈。决定下一周只改善一个主要问题，例如材料不完整，就先改善输入清单；交付质量不稳，就先缩小服务范围。</p><h2 id="_7-给继续经营设置条件" tabindex="-1">7. 给继续经营设置条件 <a class="header-anchor" href="#_7-给继续经营设置条件" aria-label="Permalink to &quot;7. 给继续经营设置条件&quot;">​</a></h2><p>在 <a href="./../../templates/startup-experiment">创业实验卡</a> 中提前写下本轮可投入的时间和现金上限，以及会触发暂停接单的情况：已有承诺无法兑现、关键资料无权使用、返工持续超出可承担范围。停止新增承诺不等于放弃已承担的责任，仍需完成交接和解释。</p><p>可以继续的证据包括：相近范围下能反复交付、全部工时逐渐可预测、回款按约发生，且有空间承担支持和例外。这样的记录比“这个月特别忙”更能解释下一步。更多 AI 服务场景见 <a href="./../part-3/2-ai-development-and-resource-layer">项目开发与资源层创业</a>，个人经历见 <a href="./../part-2/entrepreneurship">创业篇</a>。</p><h2 id="用英语解释一单生意" tabindex="-1">用英语解释一单生意 <a class="header-anchor" href="#用英语解释一单生意" aria-label="Permalink to &quot;用英语解释一单生意&quot;">​</a></h2><blockquote><p>The service brought in 1,200 yuan and required seven hours of work. After the listed cash costs and an assumed value for our time, 290 yuan remained before shared overhead and other uncounted costs. That is not net profit. We need to reduce unplanned revisions before increasing capacity.</p></blockquote><p>关键词：<strong>scope of work</strong>（工作范围）、<strong>acceptance criteria</strong>（验收标准）、<strong>rework</strong>（返工）、<strong>payment received</strong>（已到账款项）、<strong>delivery capacity</strong>（交付容量）。</p>',36)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
